1	import { isNavigable, type Dock, type ShipTuning } from "@pirate-sea-race/content";
2	import type { SimulationConfig } from "./config.js";
3	import { divTrunc } from "./fixed.js";
4	import { HEADING_DX, HEADING_DY, HEADING_SCALE, normalizeHeading } from "./heading.js";
5	import { AXIS_SCALE, INTERACT_BUTTON, sanitizeInput, type PlayerInput } from "./input.js";
6	import { NOT_DOCKED, tileCentre, WORLD_STEP_INTERVAL, type MatchState, type ShipState } from "./state.js";
7	
8	/** Held inputs by ship id; a ship without an entry is neutral. */
9	export type StepInputs = Readonly<Record<string, PlayerInput>>;
10	
11	export function isWorldStep(frame: number): boolean {
12	  return frame % WORLD_STEP_INTERVAL === 0;
13	}
14	
15	/**
16	 * Advances the match clock by one 60 Hz step and returns the new state. World logic (sailing) runs only when the new
17	 * frame is a multiple of WORLD_STEP_INTERVAL. The input state is never mutated.
18	 */
19	export function step(config: SimulationConfig, state: MatchState, inputs: StepInputs): MatchState {
20	  const frame = state.frame + 1;
21	  if (!isWorldStep(frame)) return { ...state, frame };
22	  return {
23	    ...state,
24	    frame,
25	    worldTick: state.worldTick + 1,
26	    ships: state.ships.map((ship) => sail(config, ship, sanitizeInput(inputs[ship.id]))),
27	  };
28	}
29	
30	/**
31	 * One world step of one ship (§3). The throttle (`-moveY`) accelerates, brakes or reverses; `moveX` turns the
32	 * heading; the ship then moves along its heading and stops or slides against land, shoals and the map edge.
33	 *
34	 * Docking: interact at low speed near a dock moors the ship there (at the dock tile's centre, speed 0), if its hull
35	 * could sail straight there. The throttle does not matter, so a ship driven into its dock with ahead still held (and
36	 * stopped against the shore) docks too. A moored ship stays put while interact is held, without throttle, or while
37	 * the throttle it moored with is still held; releasing that throttle and then any throttle (or the other direction)
38	 * casts off and sails in the same step.
39	 */
40	export function sail(config: SimulationConfig, ship: ShipState, input: PlayerInput): ShipState {
41	  const tuning = config.ship;
42	  const throttle = -input.moveY;
43	  const interact = (input.buttons & INTERACT_BUTTON) !== 0;
44	  const direction = Math.sign(throttle);
45	  let dock = ship.dock;
46	  if (dock !== NOT_DOCKED) {
47	    if (direction === 0 || interact || direction === ship.mooredThrottle) {
48	      const mooredThrottle = direction === 0 ? 0 : ship.mooredThrottle;
49	      return ship.speed === 0 && ship.mooredThrottle === mooredThrottle ? ship : { ...ship, speed: 0, mooredThrottle };
50	    }
51	    dock = NOT_DOCKED;
52	  } else if (interact && Math.abs(ship.speed) <= tuning.dockMaxSpeed) {
53	    const berth = dockInReach(config, ship.x, ship.y);
54	    if (berth !== undefined) {
55	      return { ...ship, ...tileCentre(config, berth.tileX, berth.tileY), speed: 0, dock: berth.id, mooredThrottle: direction };
56	    }
57	  }
58	
59	  const heading = normalizeHeading(ship.heading + Math.sign(input.moveX) * tuning.turnRate);
60	  const speed = nextSpeed(tuning, ship.speed, throttle);
61	  const dx = divTrunc(speed * HEADING_DX[heading]!, HEADING_SCALE);
62	  const dy = divTrunc(speed * HEADING_DY[heading]!, HEADING_SCALE);
63	  const x = sweepX(config, ship.x, ship.y, dx);
64	  const y = sweepY(config, x, ship.y, dy);
65	  // Blocked on every axis it tried to move along: the ship has run aground and stops. Blocked on one axis only, it
66	  // slides along the obstacle on the other.
67	  const aground = (dx !== 0 || dy !== 0) && x === ship.x && y === ship.y;
68	  return { ...ship, x, y, heading, speed: aground ? 0 : speed, dock, mooredThrottle: 0 };
69	}
70	
71	/** The speed after one world step of throttle in [-AXIS_SCALE, AXIS_SCALE] (positive forward). */
72	export function nextSpeed(tuning: ShipTuning, speed: number, throttle: number): number {
73	  if (throttle > 0) {
74	    if (speed < 0) return Math.min(speed + tuning.braking, 0);
75	    const target = divTrunc(tuning.maxSpeed * throttle, AXIS_SCALE);
76	    return speed < target ? Math.min(speed + tuning.acceleration, target) : Math.max(speed - tuning.drag, target);
77	  }
78	  if (throttle < 0) {
79	    // Down brakes a ship under way, and reverses slowly from a stop.
80	    if (speed > 0) return Math.max(speed - tuning.braking, 0);
81	    const target = -divTrunc(tuning.maxReverseSpeed * -throttle, AXIS_SCALE);
82	    return speed > target ? Math.max(speed - tuning.reverseAcceleration, target) : Math.min(speed + tuning.drag, target);
83	  }
84	  return speed > 0 ? Math.max(speed - tuning.drag, 0) : Math.min(speed + tuning.drag, 0);
85	}
86	
87	/**
88	 * The nearest dock whose tile centre is within the dock radius of a position and that the hull can reach in a straight
89	 * line without touching land or a shoal, or undefined. Mooring moves the ship to that centre, so without the path
90	 * check it could cut a corner of land that sailing would have stopped it at.
91	 */
92	export function dockInReach(config: SimulationConfig, x: number, y: number): Dock | undefined {
93	  const reach = config.ship.dockRadius * config.ship.dockRadius;
94	  let best: Dock | undefined;
95	  let bestDistance = reach + 1;
96	  for (const dock of config.map.docks) {
97	    const centre = tileCentre(config, dock.tileX, dock.tileY);
98	    const distance = (centre.x - x) * (centre.x - x) + (centre.y - y) * (centre.y - y);
99	    if (distance < bestDistance && hullPathIsClear(config, x, y, centre.x, centre.y)) {
100	      best = dock;
101	      bestDistance = distance;
102	    }
103	  }
104	  return best;
105	}
106	
107	/**
108	 * The hull is a square of `hullHalfSize` around the position. It never overlaps a blocked tile, so a move only needs
109	 * to check the tile columns (or rows) its leading edge enters, in order: the first blocked one stops the hull flush
110	 * against it. However fast the ship, it cannot pass through a tile, so it never tunnels.
111	 */
112	function sweepX(config: SimulationConfig, x: number, y: number, dx: number): number {
113	  if (dx === 0) return x;
114	  const size = config.map.subUnitsPerTile;
115	  const half = config.ship.hullHalfSize;
116	  const top = Math.floor((y - half) / size);
117	  const bottom = Math.floor((y + half) / size);
118	  const blocked = (column: number) => {
119	    for (let row = top; row <= bottom; row++) if (!isNavigable(config.map, column, row)) return true;
120	    return false;
121	  };
122	  if (dx > 0) {
123	    const last = Math.floor((x + half + dx) / size);
124	    for (let column = Math.floor((x + half) / size) + 1; column <= last; column++) {
125	      if (blocked(column)) return column * size - 1 - half;
126	    }
127	  } else {
128	    const last = Math.floor((x - half + dx) / size);
129	    for (let column = Math.floor((x - half) / size) - 1; column >= last; column--) {
130	      if (blocked(column)) return (column + 1) * size + half;
131	    }
132	  }
133	  return x + dx;
134	}
135	
136	function sweepY(config: SimulationConfig, x: number, y: number, dy: number): number {
137	  if (dy === 0) return y;
138	  const size = config.map.subUnitsPerTile;
139	  const half = config.ship.hullHalfSize;
140	  const left = Math.floor((x - half) / size);
141	  const right = Math.floor((x + half) / size);
142	  const blocked = (row: number) => {
143	    for (let column = left; column <= right; column++) if (!isNavigable(config.map, column, row)) return true;
144	    return false;
145	  };
146	  if (dy > 0) {
147	    const last = Math.floor((y + half + dy) / size);
148	    for (let row = Math.floor((y + half) / size) + 1; row <= last; row++) {
149	      if (blocked(row)) return row * size - 1 - half;
150	    }
151	  } else {
152	    const last = Math.floor((y - half + dy) / size);
153	    for (let row = Math.floor((y - half) / size) - 1; row >= last; row--) {
154	      if (blocked(row)) return (row + 1) * size + half;
155	    }
156	  }
157	  return y + dy;
158	}
159	
160	/**
161	 * Whether the hull stays clear along the straight segment between two positions. It checks every position one
162	 * sub-unit apart along the longer axis, so between two checks the hull moves at most one sub-unit on either axis and
163	 * no tile corner can slip between them.
164	 */
165	export function hullPathIsClear(config: SimulationConfig, fromX: number, fromY: number, toX: number, toY: number): boolean {
166	  const dx = toX - fromX;
167	  const dy = toY - fromY;
168	  const steps = Math.max(Math.abs(dx), Math.abs(dy));
169	  if (steps === 0) return hullIsClear(config, fromX, fromY);
170	  for (let index = 0; index <= steps; index++) {
171	    if (!hullIsClear(config, fromX + divTrunc(dx * index, steps), fromY + divTrunc(dy * index, steps))) return false;
172	  }
173	  return true;
174	}
175	
176	/** Whether a ship's hull at (x, y) overlaps only navigable tiles. Tests use it to check the collision invariant. */
177	export function hullIsClear(config: SimulationConfig, x: number, y: number): boolean {
178	  const size = config.map.subUnitsPerTile;
179	  const half = config.ship.hullHalfSize;
180	  for (let row = Math.floor((y - half) / size); row <= Math.floor((y + half) / size); row++) {
181	    for (let column = Math.floor((x - half) / size); column <= Math.floor((x + half) / size); column++) {
182	      if (!isNavigable(config.map, column, row)) return false;
183	    }
184	  }
185	  return true;
186	}
