31	 * A diagonal step needs both tiles beside it free, since a hull cannot squeeze between two blocked corners.
32	 */
33	export function seaPathCosts(map: SeaMapDefinition, fromX: number, fromY: number): Float64Array {
34	  const width = map.widthTiles;
35	  const costs = new Float64Array(width * map.heightTiles).fill(UNREACHABLE);
36	  if (!isNavigable(map, fromX, fromY)) return costs;
37	  const step = octileStepCosts(map.subUnitsPerTile);
38	  const heap = new MinHeap();
39	  const start = fromY * width + fromX;
40	  costs[start] = 0;
41	  heap.push(0, start);
42	  while (heap.size > 0) {
43	    const [cost, index] = heap.pop();
44	    if (cost > costs[index]!) continue;
45	    const x = index % width;
46	    const y = (index - x) / width;
47	    for (let dy = -1; dy <= 1; dy++) {
48	      for (let dx = -1; dx <= 1; dx++) {
49	        if (dx === 0 && dy === 0) continue;
