247	function boundsOf(islands: SeaMapDefinition["islands"]) {
248	  if (islands.length === 0) return undefined;
249	  return {
250	    minX: Math.min(...islands.map((island) => island.tileX)),
251	    minY: Math.min(...islands.map((island) => island.tileY)),
252	    maxX: Math.max(...islands.map((island) => island.tileX + island.widthTiles - 1)),
